import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.z3u3TMv0.js";const f=JSON.parse('{"title":"生圖模型部署","description":"本機部署 A1111 或 ComfyUI，MiniTavern 局域網生圖；無雲端生圖 API 時的本地 Stable Diffusion 方案。","frontmatter":{"title":"生圖模型部署","description":"本機部署 A1111 或 ComfyUI，MiniTavern 局域網生圖；無雲端生圖 API 時的本地 Stable Diffusion 方案。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"生圖模型部署 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"本機部署 A1111 或 ComfyUI，MiniTavern 局域網生圖；無雲端生圖 API 時的本地 Stable Diffusion 方案。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/local/image-gen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/local/image-gen"}]]},"headers":[],"relativePath":"zh-TW/local/image-gen/index.md","filePath":"zh-TW/local/image-gen/index.md","lastUpdated":1787224147000}'),i={name:"zh-TW/local/image-gen/index.md"};function n(d,t,l,h,c,s){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="生圖模型部署" tabindex="-1">生圖模型部署 <a class="header-anchor" href="#生圖模型部署" aria-label="Permalink to &quot;生圖模型部署&quot;">​</a></h1><p>MiniTavern 支持雲端生圖（OpenAI / Gemini / OpenRouter / Qwen）與<strong>本機</strong> Stable Diffusion 系服務：</p><table tabindex="0"><thead><tr><th>本機後端</th><th>App 平臺</th><th>默認端口</th></tr></thead><tbody><tr><td><a href="./a1111">AUTOMATIC1111 / SD WebUI</a></td><td>A1111(SD WebUI)</td><td><code>7860</code></td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>ComfyUI</td><td><code>8188</code>（Desktop 常見 <code>8000</code>）</td></tr></tbody></table><p>手機上的 MiniTavern <strong>不在手機裡跑</strong>擴散模型；圖在電腦（或雲 GPU）生成，App 只發請求並展示結果。</p><h2 id="你需要什麼" tabindex="-1">你需要什麼 <a class="header-anchor" href="#你需要什麼" aria-label="Permalink to &quot;你需要什麼&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>建議</th></tr></thead><tbody><tr><td>電腦</td><td>Windows 最省事；macOS / Linux 也可</td></tr><tr><td>顯卡</td><td><strong>NVIDIA 6GB+</strong> 較舒適（SD 1.5）；SDXL / 較大模型建議 <strong>8–12GB+</strong></td></tr><tr><td>無獨顯</td><td>可試 CPU（很慢）或租用雲 GPU（按小時計費，非免費）</td></tr><tr><td>網絡</td><td>手機與電腦同一 Wi‑Fi（勿用訪客隔離網）</td></tr><tr><td>磁盤</td><td>模型文件常 <strong>2–10GB+</strong> / 個，預留空間</td></tr></tbody></table><p>沒有 GPU、也不想部署時：可用 <a href="/ultra_guides/zh-TW/free-cloud/#免費生圖怎麼配">免費雲端 · 生圖</a> 裡的雲端免費圖像檔（若有），或暫只聊天不生圖。</p><h2 id="選哪條路徑" tabindex="-1">選哪條路徑 <a class="header-anchor" href="#選哪條路徑" aria-label="Permalink to &quot;選哪條路徑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>適合誰</th><th>難度</th></tr></thead><tbody><tr><td><a href="./a1111">A1111</a></td><td>想要傳統 WebUI、參數直觀、與酒館生態常見對接</td><td>中</td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>想要工作流 / 新模型支持快；App 使用內置默認 workflow</td><td>中</td></tr></tbody></table><p>兩條路徑最後都要：<a href="./connect-app">在 MiniTavern 中配置生圖連接</a>。</p><h2 id="推薦閱讀順序" tabindex="-1">推薦閱讀順序 <a class="header-anchor" href="#推薦閱讀順序" aria-label="Permalink to &quot;推薦閱讀順序&quot;">​</a></h2><ol><li>按硬件選 <a href="./a1111">A1111</a> 或 <a href="./comfyui">ComfyUI</a> 完成安裝與下載模型</li><li>開啟 <strong>API + 局域網監聽</strong>（各教程內有說明）</li><li><a href="./connect-app">連接 MiniTavern</a> 並測連</li><li>在聊天裡用 <code>/imagine</code> 或附件 → 生圖（見 <a href="/ultra_guides/zh-TW/manual/model-link#生圖連接--智能--關鍵詞">模型連接 · 生圖</a>）</li><li>返回 <a href="/ultra_guides/zh-TW/local/">部署本地模型</a> 總覽</li></ol><h2 id="重要提醒" tabindex="-1">重要提醒 <a class="header-anchor" href="#重要提醒" aria-label="Permalink to &quot;重要提醒&quot;">​</a></h2><ul><li>手機裡填的地址必須是電腦的 <strong>局域網 IP</strong>（如 <code>192.168.1.8</code>），<strong>不要</strong>填 <code>localhost</code> / <code>127.0.0.1</code>。</li><li>A1111 必須帶 <strong><code>--api</code></strong>；僅開 Web 界面不夠。</li><li>ComfyUI 需 <strong><code>--listen</code></strong>（或 Desktop 裡 Listen 設為 <code>0.0.0.0</code>）才能被手機訪問。</li><li>防火牆放行對應端口；不要把未鑑權的生圖 API 暴露到公網。</li><li>當前 App 的 Comfy 默認工作流<strong>不消費參考圖</strong>；需要鎖臉時優先 A1111 或雲端支持參考圖的平臺。</li></ul>',14)])])}const m=e(i,[["render",n]]);export{f as __pageData,m as default};
